def ulam_sequence(u0, u1, n):
    if n < 2:
        raise ValueError("n must be greater than 1")
    if u0 < 1 or u1 < 1:
        raise ValueError("u0 and u1 must be greater than or equal to 1")

    sequence = [u0, u1]
    sums = {u0 + u1}

    while len(sequence) < n:
        candidates = set()
        for i in range(len(sequence)):
            for j in range(i + 1, len(sequence)):
                candidate = sequence[i] + sequence[j]
                if candidate > sequence[-1] and candidate not in sums:
                    candidates.add(candidate)
        if not candidates:
            raise ValueError("No more valid terms can be generated")
        sequence.append(min(candidates))
        sums.add(sequence[-1])
    return sequence

